import json
class CookiesUtil:  
    """
    This is a class as utility for managing and manipulating Cookies, including methods for retrieving, saving, and setting Cookies data.
    """

    def __init__(self, cookies_file):
        """
        Initializes the CookiesUtil with the specified cookies file.
        :param cookies_file: The cookies file to use, str.
        """
        self.cookies_file = cookies_file
        self.cookies = None



    def get_cookies(self, reponse):
        """
        Gets the cookies from the specified response,and save it to cookies_file.
        :param reponse: The response to get cookies from, dict.
        >>> cookies_util = CookiesUtil('cookies.json')
        >>> cookies_util.get_cookies({'cookies': {'key1': 'value1', 'key2': 'value2'}})
        >>> cookies_util.cookies
        {'key1': 'value1', 'key2': 'value2'}

        """
        if not self.cookies:
            self.cookies = self.get_cookies_from_response(reponse)
        return self.cookies


    def get_cookies_from_response(self, response):
        """
        Gets the cookies from the specified response,and save it to cookies_file.
        :param response: The response to get cookies from, dict.
        >>> cookies_util = CookiesUtil('cookies.json')
        >>> cookies_util.get_cookies({'cookies': {'key1': 'value1', 'key2': 'value2'}})
        >>> cookies_util.cookies
        {'key1': 'value1', 'key2': 'value2'}
        """
        if not response:
            return {}
        if 'cookies' in response:
            return response['cookies']
        else:
            return {}


    def set_cookies(self, cookies):
        """
        Sets the cookies to the specified cookies,and saves it to cookies_file.
        :param cookies: The cookies to set, dict.
        >>> cookies_util = CookiesUtil('cookies.json')
        >>> cookies_util.set_cookies({'cookies': {'key1': 'value1', 'key2': 'value2'}})
        >>> cookies_util.cookies
        {'key1': 'value1', 'key2': 'value2'}
        """
        if not cookies:
            return
        self.cookies = cookies
        self.cookies_file = open(self.cookies_file, 'w')
        self.cookies_file.write(json.dumps(cookies, indent=4))
        self.cookies_file.close()


    def save_cookies(self, cookies):
        """
        Saves the cookies to cookies_file.
        :param cookies: The cookies to save, dict.
        >>> cookies_util = CookiesUtil('cookies.json')
        >>> cookies_util.save_cookies({'cookies': {'key1': 'value1', 'key2': 'value2'}})
        >>> cookies_util.cookies
        {'key1': 'value1', 'key2': 'value2'}
        """
        if not cookies:
            return
        self.cookies_file.write(json.dumps(cookies, indent=4))
        self.cookies_file.close()


    def delete_cookies(self, cookies):
        """
        Deletes the cookies from cookies_file.
        :param cookies: The cookies to delete, dict.
        >>> cookies_util = CookiesUtil('cookies.json')
        >>> cookies_util.delete_cookies({'cookies': {'key1': 'value1', 'key2': 'value2'}})
        >>> cookies_util.cookies
        {}
        """
        if not cookies:
            return
        self.cookies_file.write(json.dumps(cookies, indent=4))
        self.cookies_file.close()


    def delete_cookies_from_response(self, response):
        """
        Deletes the cookies from the specified response,and saves it to cookies_file.
        :param response: The response to delete cookies from, dict.
        >>> cookies_util = CookiesUtil('cookies.json')
        >>> cookies_util.delete_cookies({'cookies': {'key1': 'value1', 'key2': 'value2'}})
        >>> cookies_util.cookies
        {}
        """
        if not response:
            return
        if 'cookies' in response:
            self.delete_cookies(response['cookies'])
        else:
            self.delete_cookies(response)
        self.cookies_file.write(json.dumps(response, indent=4))
        self.cookies_file.close()


    def delete_cookies_from_response_file(self, response_file):
